-- Catalog-only PostgreSQL18 inspection. No application rows, credentials or
-- function bodies. Run only with an existing owner-authorized observation route.
-- Use PGOPTIONS for timeouts/default_transaction_read_only and TLS verify-full.
-- Role names returned here are private metadata: redact/alias before publication.
\set QUIET on
BEGIN READ ONLY;
-- Never inherit candidate-controlled function/operator/type lookup. Keep temporary
-- types after pg_catalog as well; read-only alone does not prohibit row reads.
SET LOCAL search_path = pg_catalog, pg_temp;
SELECT jsonb_build_object(
 'identity',jsonb_build_object('currentUser',current_user,'sessionUser',session_user,'currentEqualsSession',current_user=session_user,'currentRoleOid',(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=current_user),'sessionRoleOid',(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=session_user),'databaseOid',(SELECT oid FROM pg_catalog.pg_database WHERE datname=current_database())),
 'transactionReadOnly',current_setting('transaction_read_only'),
 'defaultTransactionReadOnly',current_setting('default_transaction_read_only'),
 'serverMajor',current_setting('server_version_num')::int / 10000,
 'role', (SELECT jsonb_build_object('superuser',rolsuper,'createRole',rolcreaterole,'createDatabase',rolcreatedb,'replication',rolreplication,'bypassRls',rolbypassrls,'inherit',rolinherit,'login',rolcanlogin) FROM pg_catalog.pg_roles WHERE rolname=current_user),
 'database', (SELECT jsonb_build_object('currentRoleOwns',datdba=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=current_user),'inheritsOwner',pg_has_role(current_user,datdba,'USAGE'),'canSetOwnerRole',pg_has_role(current_user,datdba,'SET'),'canCreateSchema',has_database_privilege(current_user,oid,'CREATE'),'canCreateTemporary',has_database_privilege(current_user,oid,'TEMPORARY')) FROM pg_catalog.pg_database WHERE datname=current_database()),
 'publicSchema', (SELECT jsonb_build_object('currentRoleOwns',nspowner=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=current_user),'inheritsOwner',pg_has_role(current_user,nspowner,'USAGE'),'canSetOwnerRole',pg_has_role(current_user,nspowner,'SET'),'create',has_schema_privilege(current_user,oid,'CREATE'),'usage',has_schema_privilege(current_user,oid,'USAGE')) FROM pg_catalog.pg_namespace WHERE nspname='public'),
 'publicTables',(SELECT jsonb_build_object('count',count(*),'ownedByCurrentRole',count(*) FILTER(WHERE relowner=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=current_user)),'ownerPrivilegeInherited',count(*) FILTER(WHERE pg_has_role(current_user,relowner,'USAGE')),'ownerRoleSettable',count(*) FILTER(WHERE pg_has_role(current_user,relowner,'SET')),'rlsEnabled',count(*) FILTER(WHERE relrowsecurity),'forceRlsEnabled',count(*) FILTER(WHERE relforcerowsecurity)) FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p')),
 'sensitiveTables', (SELECT coalesce(jsonb_agg(jsonb_build_object('table',c.relname,'ownedByCurrentRole',c.relowner=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=current_user),'ownerRoleSettable',pg_has_role(current_user,c.relowner,'SET'),'select',has_table_privilege(current_user,c.oid,'SELECT'),'insert',has_table_privilege(current_user,c.oid,'INSERT'),'update',has_table_privilege(current_user,c.oid,'UPDATE'),'selectAnyColumn',has_any_column_privilege(current_user,c.oid,'SELECT'),'insertAnyColumn',has_any_column_privilege(current_user,c.oid,'INSERT'),'updateAnyColumn',has_any_column_privilege(current_user,c.oid,'UPDATE'),'delete',has_table_privilege(current_user,c.oid,'DELETE'),'truncate',has_table_privilege(current_user,c.oid,'TRUNCATE'),'trigger',has_table_privilege(current_user,c.oid,'TRIGGER'),'rls',c.relrowsecurity,'forceRls',c.relforcerowsecurity)),'[]'::jsonb) FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('__EFMigrationsHistory','AbpUsers','AbpRoles','AbpUserRoles','AbpPermissions','AbpTenants','AreaAdminAssignments','Customers','MemberPayments','EntryWeeklyCommissions','OnyxWeeklyCommissions','TransactionalEmailOutboxMessages','DataProtectionKeys')),
 'sensitiveColumns',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',c.relname,'column',a.attname,'select',has_column_privilege(current_user,c.oid,a.attnum,'SELECT'),'insert',has_column_privilege(current_user,c.oid,a.attnum,'INSERT'),'update',has_column_privilege(current_user,c.oid,a.attnum,'UPDATE'))),'[]'::jsonb) FROM pg_catalog.pg_attribute a JOIN pg_catalog.pg_class c ON c.oid=a.attrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND a.attnum>0 AND NOT a.attisdropped AND ((c.relname='AbpUsers' AND a.attname IN ('Name','Password','SecurityStamp','EmailAddress','Role','TenantId','IsActive','IsDeleted')) OR (c.relname='Customers' AND a.attname IN ('TenantId','AreaId','MembershipId','UserId')) OR (c.relname='TransactionalEmailOutboxMessages' AND a.attname IN ('TenantId','Recipient','Status','ProviderMessageId','SentAt','AttemptCount')))),
 'otherLoginRoles',(SELECT count(*) FROM pg_catalog.pg_roles WHERE rolcanlogin AND rolname<>current_user),
 'reachableDangerousRoles',(SELECT coalesce(jsonb_agg(jsonb_build_object('builtInName',CASE WHEN rolname ~ '^(pg_|postgres$|render_superuser$)' THEN rolname ELSE 'OTHER_ROLE' END,'inherit',pg_has_role(current_user,oid,'USAGE'),'set',pg_has_role(current_user,oid,'SET'),'superuser',rolsuper,'createRole',rolcreaterole,'createDatabase',rolcreatedb,'replication',rolreplication,'bypassRls',rolbypassrls)),'[]'::jsonb) FROM pg_catalog.pg_roles WHERE rolname<>current_user AND (rolsuper OR rolcreaterole OR rolcreatedb OR rolreplication OR rolbypassrls OR rolname IN ('pg_read_server_files','pg_write_server_files','pg_execute_server_program')) AND (pg_has_role(current_user,oid,'USAGE') OR pg_has_role(current_user,oid,'SET'))),
 'userSchemas',(SELECT jsonb_build_object('total',count(*),'creatable',count(*) FILTER(WHERE has_schema_privilege(current_user,oid,'CREATE'))) FROM pg_catalog.pg_namespace WHERE nspname !~ '^pg_' AND nspname<>'information_schema'),
 'userSecurityDefinerFunctions',(SELECT jsonb_build_object('total',count(*),'executable',count(*) FILTER(WHERE has_function_privilege(current_user,p.oid,'EXECUTE'))) FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname !~ '^pg_' AND n.nspname<>'information_schema' AND p.prosecdef),
 'publicSecurityDefinerFunctions',(SELECT jsonb_build_object('total',count(*),'executable',count(*) FILTER(WHERE has_function_privilege(current_user,p.oid,'EXECUTE'))) FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prosecdef),
 'roleAdministrationMemberships',(SELECT count(*) FROM pg_catalog.pg_auth_members WHERE member=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=current_user) AND admin_option),
 'server',jsonb_build_object('maxConnections',current_setting('max_connections')::int,'superuserReservedConnections',current_setting('superuser_reserved_connections')::int,'reservedConnections',current_setting('reserved_connections')::int,'rowSecuritySetting',current_setting('row_security'),'connectedBackends',(SELECT numbackends FROM pg_catalog.pg_stat_database WHERE datname=current_database())),
 'roles',(SELECT coalesce(jsonb_agg(jsonb_build_object('oid',oid,'name',rolname,'login',rolcanlogin,'superuser',rolsuper,'createRole',rolcreaterole,'createDatabase',rolcreatedb,'replication',rolreplication,'bypassRls',rolbypassrls,'inherit',rolinherit,'connectionLimit',rolconnlimit) ORDER BY oid),'[]'::jsonb) FROM pg_catalog.pg_roles),
 'memberships',(SELECT coalesce(jsonb_agg(jsonb_build_object('roleOid',roleid,'memberOid',member,'grantorOid',grantor,'admin',admin_option,'inherit',inherit_option,'set',set_option) ORDER BY roleid,member,grantor),'[]'::jsonb) FROM pg_catalog.pg_auth_members),
 'databaseOwner',(SELECT jsonb_build_object('ownerOid',datdba,'create',has_database_privilege(current_user,oid,'CREATE'),'connect',has_database_privilege(current_user,oid,'CONNECT'),'temporary',has_database_privilege(current_user,oid,'TEMPORARY')) FROM pg_catalog.pg_database WHERE datname=current_database()),
 'schemas',(SELECT coalesce(jsonb_agg(jsonb_build_object('oid',oid,'name',nspname,'ownerOid',nspowner,'usage',has_schema_privilege(current_user,oid,'USAGE'),'create',has_schema_privilege(current_user,oid,'CREATE')) ORDER BY oid),'[]'::jsonb) FROM pg_catalog.pg_namespace WHERE nspname !~ '^pg_' AND nspname<>'information_schema'),
 'relations',(SELECT coalesce(jsonb_agg(jsonb_build_object('oid',c.oid,'schemaOid',n.oid,'name',c.relname,'kind',c.relkind,'ownerOid',c.relowner,'ownerInherited',pg_has_role(current_user,c.relowner,'USAGE'),'ownerSettable',pg_has_role(current_user,c.relowner,'SET'),'select',has_table_privilege(current_user,c.oid,'SELECT'),'insert',has_table_privilege(current_user,c.oid,'INSERT'),'update',has_table_privilege(current_user,c.oid,'UPDATE'),'delete',has_table_privilege(current_user,c.oid,'DELETE'),'truncate',has_table_privilege(current_user,c.oid,'TRUNCATE'),'references',has_table_privilege(current_user,c.oid,'REFERENCES'),'trigger',has_table_privilege(current_user,c.oid,'TRIGGER'),'maintain',has_table_privilege(current_user,c.oid,'MAINTAIN'),'selectAnyColumn',has_any_column_privilege(current_user,c.oid,'SELECT'),'insertAnyColumn',has_any_column_privilege(current_user,c.oid,'INSERT'),'updateAnyColumn',has_any_column_privilege(current_user,c.oid,'UPDATE'),'rlsApplicable',c.relkind IN ('r','p'),'rlsEnabled',c.relrowsecurity,'forceRlsEnabled',c.relforcerowsecurity,'rlsActive',CASE WHEN c.relkind IN ('r','p') THEN row_security_active(c.oid) ELSE NULL END) ORDER BY c.oid),'[]'::jsonb) FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname !~ '^pg_' AND n.nspname<>'information_schema' AND c.relkind IN ('r','p','v','m','f')),
 'sequences',(SELECT coalesce(jsonb_agg(jsonb_build_object('oid',c.oid,'schemaOid',n.oid,'name',c.relname,'ownerOid',c.relowner,'ownerInherited',pg_has_role(current_user,c.relowner,'USAGE'),'ownerSettable',pg_has_role(current_user,c.relowner,'SET'),'usage',has_sequence_privilege(current_user,c.oid,'USAGE'),'select',has_sequence_privilege(current_user,c.oid,'SELECT'),'update',has_sequence_privilege(current_user,c.oid,'UPDATE')) ORDER BY c.oid),'[]'::jsonb) FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname !~ '^pg_' AND n.nspname<>'information_schema' AND c.relkind='S'),
 'routines',(SELECT coalesce(jsonb_agg(jsonb_build_object('oid',p.oid,'schemaOid',n.oid,'name',p.proname,'ownerOid',p.proowner,'kind',p.prokind,'securityDefiner',p.prosecdef,'execute',has_function_privilege(current_user,p.oid,'EXECUTE'),'ownerInherited',pg_has_role(current_user,p.proowner,'USAGE'),'ownerSettable',pg_has_role(current_user,p.proowner,'SET'),'argumentTypeOids',p.proargtypes::oid[],'returnTypeOid',p.prorettype) ORDER BY p.oid),'[]'::jsonb) FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname !~ '^pg_' AND n.nspname<>'information_schema'),
 'policies',(SELECT coalesce(jsonb_agg(jsonb_build_object('oid',p.oid,'tableOid',p.polrelid,'name',p.polname,'command',p.polcmd,'roleOids',p.polroles,'permissive',p.polpermissive,'usingExpressionPresent',p.polqual IS NOT NULL,'checkExpressionPresent',p.polwithcheck IS NOT NULL) ORDER BY p.oid),'[]'::jsonb) FROM pg_catalog.pg_policy p JOIN pg_catalog.pg_class c ON c.oid=p.polrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname !~ '^pg_' AND n.nspname<>'information_schema'),
 'defaultPrivileges',(SELECT coalesce(jsonb_agg(jsonb_build_object('ownerOid',d.defaclrole,'schemaOid',d.defaclnamespace,'objectType',d.defaclobjtype,'grantorOid',a.grantor,'granteeOid',a.grantee,'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY d.oid,a.grantee,a.privilege_type),'[]'::jsonb) FROM pg_catalog.pg_default_acl d CROSS JOIN LATERAL pg_catalog.aclexplode(d.defaclacl) a),
 'roleSettings',(SELECT coalesce(jsonb_agg(jsonb_build_object('databaseOid',s.setdatabase,'roleOid',s.setrole,'settingNames',(SELECT jsonb_agg(split_part(setting,'=',1)) FROM unnest(s.setconfig) setting)) ORDER BY s.setdatabase,s.setrole),'[]'::jsonb) FROM pg_catalog.pg_db_role_setting s WHERE s.setdatabase IN (0,(SELECT oid FROM pg_catalog.pg_database WHERE datname=current_database()))),
 'activeRoleConnections',(SELECT coalesce(jsonb_agg(jsonb_build_object('roleOid',role_oid,'connections',connections) ORDER BY role_oid),'[]'::jsonb) FROM (SELECT usesysid AS role_oid,count(*) AS connections FROM pg_catalog.pg_stat_activity WHERE datid=(SELECT oid FROM pg_catalog.pg_database WHERE datname=current_database()) AND usesysid IS NOT NULL GROUP BY usesysid) connections)
);
ROLLBACK;
